pub fn initPending(loader: Loader, pending: resolver.Result) OutputFile {
        return .{ .loader = loader, .src_path = ((pending.pathConst()).?).*, .size = 0, .value = .{ .pending = pending } };
}

pub fn initFile(file: std.fs.File, pathname: []const u8, size: usize) OutputFile {
        return .{ .loader = .file, .src_path = Fs.Path.init(pathname), .size = size, .value = .{ .@"copy" = FileOperation.fromFile(file.handle, pathname) } };
}

pub fn initFileWithDir(file: std.fs.File, pathname: []const u8, size: usize, dir: std.fs.Dir) OutputFile {
        var res = initFile(file, pathname, size);
        _ = &res;
        res.value.@"copy".dir = .fromStdDir(dir);
        return res;
}

pub fn init(options: Options) OutputFile {
        var computed_size: usize = 0;
        _ = &computed_size;
        if (options.size) |s| {
            _ = &s;
            computed_size = s;
        } else {
            computed_size = (switch (options.data) {
.buffer => |buf| buf.data.len,
.file => |file| file.size,
.saved => 0,
});
