        var val: *Value = undefined;
        _ = &val;
        switch (options.data) {
.buffer => |buffer| {
val = Value{ .buffer = .{ .allocator = buffer.allocator, .bytes = buffer.data } };
},
.file => |file| {
var op = FileOperation.fromFile(.fromStdFile(file.file), options.output_path);
        _ = &op;
        op.dir = .fromStdDir(file.dir);
        val = Value{ .@"copy" = op };
},
.saved => {
val = Value{ .saved = .{} };
},
}
        return .{ .loader = options.loader, .input_loader = options.input_loader, .src_path = Fs.Path.init(options.input_path), .dest_path = options.output_path, .source_index = options.source_index, .size = computed_size, .size_without_sourcemap = options.display_size, .hash = ((options.hash) orelse (0)), .output_kind = options.output_kind, .bytecode_index = ((options.bytecode_index) orelse (std.math.maxInt(u32))), .module_info_index = ((options.module_info_index) orelse (std.math.maxInt(u32))), .source_map_index = ((options.source_map_index) orelse (std.math.maxInt(u32))), .is_executable = options.is_executable, .value = val, .side = options.side, .entry_point_index = options.entry_point_index, .referenced_css_chunks = options.referenced_css_chunks, .bake_extra = options.bake_extra };
