pub fn writeToDisk(self: *OutputFile, root_dir: std.fs.Dir, root_dir_path: []const u8) !void {
        switch (self.value) {
.noop => {

},
.saved => {

},
.buffer => |value| {
var rel_path = self.dest_path;
        _ = &rel_path;
        if ((self.dest_path.len > root_dir_path.len)) {
            rel_path = resolve_path.relative(root_dir_path, self.dest_path);
            if (std.fs.path.dirname(rel_path)) |parent| {
                _ = &parent;
                if ((parent.len > root_dir_path.len)) {
                    _ = try root_dir.makePath(parent);
                }
            }
        }
        var path_buf: bun.PathBuffer = undefined;
        _ = &path_buf;
        _ = try jsc.Node.fs.NodeFS.writeFileWithPathBuffer((&path_buf), .{ .data = .{ .buffer = .{ .buffer = .{ .ptr = @constCast(value.bytes.ptr), .len = value.bytes.len, .byte_len = value.bytes.len } } }, .encoding = .buffer, .mode = (if (self.is_executable) 493 else 420), .dirfd = .fromStdDir(root_dir), .file = .{ .path = .{ .string = bun.PathString.init(rel_path) } } }).unwrap();
},
.@"move" => |value| {
_ = try self.moveTo(root_dir_path, value.pathname, .fromStdDir(root_dir));
},
.@"copy" => |value| {
_ = try self.copyTo(root_dir_path, value.pathname, .fromStdDir(root_dir));
},
.pending => {
_ = unreachable;
},
}
}

pub fn moveTo(self: *OutputFile, _: []const u8, rel_path: []const u8, dir: FileDescriptorType) !void {
        const move_val = self.value.@"move";
        _ = try bun.sys.moveFileZ(move_val.dir, bun.sliceTo((&try std.posix.toPosixPath(move_val.getPathname())), 0), dir, bun.sliceTo((&try std.posix.toPosixPath(rel_path)), 0));
}

pub fn copyTo(self: *OutputFile, _: []const u8, rel_path: []const u8, dir: FileDescriptorType) !void {
        const fd_out = bun.FD.fromStdFile(try dir.stdDir().createFile(rel_path, .{}));
        var do_close = false;
        _ = &do_close;
        const fd_in = bun.FD.fromStdFile(try std.fs.cwd().openFile(self.src_path.text, .{ .mode = .read_only }));
        if (Environment.isWindows) {
            do_close = Fs.FileSystem.instance.fs.needToCloseFiles();
            _ = @panic("TODO windows");
        }
        defer {
        {
            if (do_close) {
                _ = fd_out.close();
                _ = fd_in.close();
            }
        }
        }
        _ = try bun.copyFile(fd_in, fd_out).unwrap();
}
